// The /why essay is locked: every sentence, word for word, in order.
// test/fixtures/why-essay.txt was generated by essayText() from the page
// as it stood before the restaging (P1, step 1) and checked by eye against
// it. Restaging may split paragraphs at sentence boundaries and add
// aria-hidden art; it may not change what a reader hears. One deliberate
// change since: the hero's "Why fathom" eyebrow, a label repeating the h1
// (not a sentence of the essay), was dropped and the fixture regenerated.
import { render } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { readFileSync } from "node:fs";
import path from "node:path";
import WhyPage from "@/app/why/page";
import { essayText } from "./essay-text";
import { britishSpellings, capitalizedFathom, emDashes, retiredTerms, straightQuotes } from "../helpers/copy-rules";

const FIXTURE = readFileSync(path.resolve(__dirname, "../fixtures/why-essay.txt"), "utf8").trim();

const FOCUSABLE = "a[href], button, input, select, textarea, iframe, [tabindex], [contenteditable='true']";

describe("/why locked copy", () => {
  it("reads word for word, in order, as the page did before the restaging", () => {
    const { container } = render(<WhyPage />);
    expect(essayText(container)).toBe(FIXTURE);
  });

  it("draws the pivot's words from the sentence a screen reader hears, once", () => {
    const { container } = render(<WhyPage />);
    const line = container.querySelector(".why-pivot-line")!;
    const spoken = line.querySelector(".sr-only")!.textContent;
    const drawn = line.querySelector('.why-words[aria-hidden="true"]')!;
    const words = Array.from(drawn.querySelectorAll("[data-why-word]")).map((w) => w.textContent);
    expect(words.join(" ")).toBe(spoken);
    expect(essayText(line)).toBe(spoken);
  });

  it("keeps the site's copy rules (ZoomText is a product name, not the retired zoom claim)", () => {
    const { container } = render(<WhyPage />);
    const text = essayText(container);
    expect(emDashes(text)).toEqual([]);
    expect(britishSpellings(text)).toEqual([]);
    expect(straightQuotes(text)).toEqual([]);
    expect(capitalizedFathom(text)).toEqual([]);
    expect(retiredTerms(text.split("ZoomText").join(" "))).toEqual([]);
    expect(retiredTerms(text)).toEqual(["Zoom"]); // the one ZoomText mention, nothing else
  });

  it("puts no words and nothing focusable in the art", () => {
    const { container } = render(<WhyPage />);
    const art = container.querySelectorAll(".why-pane, .why-still, .why-iris");
    expect(art.length).toBeGreaterThan(0);
    for (const el of art) {
      expect(el.closest('[aria-hidden="true"]'), el.className).not.toBeNull();
      expect(el.textContent?.trim(), el.className).toBe("");
      expect(el.querySelectorAll(FOCUSABLE)).toHaveLength(0);
    }
    const svgs = container.querySelectorAll(".why-pane svg, .why-still svg");
    expect(svgs.length).toBeGreaterThan(0);
    for (const svg of svgs) {
      expect(svg.getAttribute("focusable")).toBe("false");
      expect(svg.closest('[aria-hidden="true"]')).not.toBeNull();
    }
  });
});
